+@page "/board"
+@using sv_81c8743ce0e84a478e1c285e8415ad7e.Services
+@inject ITaskService TaskService
+@rendermode InteractiveServer
+
+<PageTitle>Kanban Board</PageTitle>
+
+<h3 class="mb-3">Project Board</h3>
+
+@if (errorMessage is not null)
+{
+    <div class="alert alert-danger" role="alert">
+        <strong>Error:</strong> @errorMessage
+    </div>
+}
+else if (isLoading)
+{
+    <div class="d-flex justify-content-center my-5">
+        <div class="spinner-border" role="status">
+            <span class="visually-hidden">Loading…</span>
+        </div>
+    </div>
+}
+else
+{
+    @* ───── Stats Bar ───── *@
+    <div class="row g-2 mb-3">
+        <div class="col"><div class="stat-card bg-light p-2 rounded text-center"><strong>@allTasks.Count</strong><br/>Total</div></div>
+        <div class="col"><div class="stat-card bg-light p-2 rounded text-center"><strong>@ToDoTasks.Count</strong><br/>To Do</div></div>
+        <div class="col"><div class="stat-card bg-light p-2 rounded text-center"><strong>@InProgressTasks.Count</strong><br/>In Progress</div></div>
+        <div class="col"><div class="stat-card bg-light p-2 rounded text-center"><strong>@DoneTasks.Count</strong><br/>Done</div></div>
+        <div class="col"><div class="stat-card bg-light p-2 rounded text-center text-danger"><strong>@OverdueCount</strong><br/>Overdue</div></div>
+    </div>
+
+    @* ───── Search Bar ───── *@
+    <div class="mb-3">
+        <input type="text" class="form-control" placeholder="Search tasks by title…"
+               @bind="searchText" @bind:event="oninput" />
+    </div>
+
+    @* ───── Columns ───── *@
+    <div class="row g-3 board-columns">
+        @foreach (var col in columns)
+        {
+            var tasks = GetFilteredTasks(col.Status);
+            <div class="col-md-4">
+                <div class="card h-100">
+                    <div class="card-header d-flex justify-content-between align-items-center">
+                        <span class="fw-bold">@col.Name</span>
+                        <span class="badge bg-secondary rounded-pill">@tasks.Count</span>
+                    </div>
+                    <div class="card-body column-body">
+                        @foreach (var task in tasks)
+                        {
+                            <div class="task-card card mb-2">
+                                <div class="card-body p-2">
+                                    <h6 class="card-title mb-1">@task.Title</h6>
+                                    <p class="card-text mb-1 text-muted small">@task.Assignee</p>
+                                    <div class="d-flex justify-content-between align-items-center mb-1">
+                                        <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
+                                        <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
+                                    </div>
+                                    <div class="d-flex justify-content-between mt-1">
+                                        @if (col.Index > 0)
+                                        {
+                                            <button class="btn btn-sm btn-outline-secondary"
+                                                    disabled="@isUpdating"
+                                                    @onclick="() => MoveTask(task.Id, columns[col.Index - 1].Status)">
+                                                ← Move Left
+                                            </button>
+                                        }
+                                        else
+                                        {
+                                            <span></span>
+                                        }
+                                        @if (col.Index < columns.Length - 1)
+                                        {
+                                            <button class="btn btn-sm btn-outline-secondary"
+                                                    disabled="@isUpdating"
+                                                    @onclick="() => MoveTask(task.Id, columns[col.Index + 1].Status)">
+                                                Move Right →
+                                            </button>
+                                        }
+                                    </div>
+                                </div>
+                            </div>
+                        }
+
+                        @if (activeFormColumn == col.Status)
+                        {
+                            <div class="card mb-2 border-primary">
+                                <div class="card-body p-2">
+                                    <input type="text" class="form-control form-control-sm mb-1"
+                                           placeholder="Title" @bind="newTitle" />
+                                    <input type="text" class="form-control form-control-sm mb-1"
+                                           placeholder="Assignee" @bind="newAssignee" />
+                                    <select class="form-select form-select-sm mb-1" @bind="newPriority">
+                                        <option value="High">High</option>
+                                        <option value="Medium">Medium</option>
+                                        <option value="Low">Low</option>
+                                    </select>
+                                    <input type="date" class="form-control form-control-sm mb-2"
+                                           @bind="newDueDate" />
+                                    <div class="d-flex justify-content-end gap-1">
+                                        <button class="btn btn-sm btn-secondary" @onclick="CancelForm">Cancel</button>
+                                        <button class="btn btn-sm btn-primary" disabled="@isSaving"
+                                                @onclick="() => SaveTask(col.Status)">Save</button>
+                                    </div>
+                                </div>
+                            </div>
+                        }
+                    </div>
+                    <div class="card-footer text-center">
+                        <button class="btn btn-sm btn-outline-primary"
+                                @onclick="() => ShowForm(col.Status)">+ Add Task</button>
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private record ColumnDef(string Name, string Status, int Index);
+
+    private static readonly ColumnDef[] columns =
+    [
+        new("To Do", "To Do", 0),
+        new("In Progress", "In Progress", 1),
+        new("Done", "Done", 2),
+    ];
+
+    private List<TaskItem> allTasks = new();
+    private bool isLoading = true;
+    private bool isUpdating;
+    private bool isSaving;
+    private string? errorMessage;
+    private string searchText = string.Empty;
+
+    // New-task form state
+    private string? activeFormColumn;
+    private string newTitle = string.Empty;
+    private string newAssignee = string.Empty;
+    private string newPriority = "Medium";
+    private DateTime newDueDate = DateTime.Today.AddDays(7);
+
+    // Derived lists (unfiltered, used for stats)
+    private List<TaskItem> ToDoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
+    private List<TaskItem> InProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
+    private List<TaskItem> DoneTasks => allTasks.Where(t => t.Status == "Done").ToList();
+    private int OverdueCount => allTasks.Count(t => t.DueDate.Date < DateTime.Today);
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private List<TaskItem> GetFilteredTasks(string status)
+    {
+        return allTasks
+            .Where(t => t.Status == status &&
+                        (string.IsNullOrWhiteSpace(searchText) ||
+                         t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)))
+            .ToList();
+    }
+
+    private async Task MoveTask(int taskId, string newStatus)
+    {
+        isUpdating = true;
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var idx = allTasks.FindIndex(t => t.Id == taskId);
+            if (idx >= 0)
+            {
+                allTasks[idx] = allTasks[idx] with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isUpdating = false;
+        }
+    }
+
+    private void ShowForm(string status)
+    {
+        activeFormColumn = status;
+        newTitle = string.Empty;
+        newAssignee = string.Empty;
+        newPriority = "Medium";
+        newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelForm() => activeFormColumn = null;
+
+    private async Task SaveTask(string status)
+    {
+        if (string.IsNullOrWhiteSpace(newTitle))
+            return;
+
+        isSaving = true;
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(newTitle, newAssignee, newPriority, newDueDate);
+            // The service creates tasks; if the status differs from "To Do", move it.
+            if (created.Status != status)
+            {
+                await TaskService.UpdateTaskStatusAsync(created.Id, status);
+                created = created with { Status = status };
+            }
+            allTasks.Add(created);
+            activeFormColumn = null;
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isSaving = false;
+        }
+    }
+
+    private static string GetPriorityClass(string priority) => priority switch
+    {
+        "High" => "bg-danger",
+        "Medium" => "bg-warning text-dark",
+        "Low" => "bg-success",
+        _ => "bg-secondary",
+    };
+}
+

